package com.portshipping.entity;
import jakarta.persistence.*; import java.time.Instant;
@Entity @Table(name="roles",uniqueConstraints=@UniqueConstraint(name="uq_roles_name",columnNames="name")) public class Role { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(nullable=false,length=40) private String name; @Column(length=255) private String description; @Column(name="created_at") private Instant createdAt=Instant.now(); protected Role(){} public Role(String n,String d){name=n;description=d;} public Long getId(){return id;} public String getName(){return name;} public String getDescription(){return description;} public Instant getCreatedAt(){return createdAt;} }
